import{_ as t,a,c as i,ac as r}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"程序员英语 01：学习路线与能力自测","description":"用读文档、定位报错、写协作材料和说明技术方案四类任务建立程序员英语学习路线。","frontmatter":{"title":"程序员英语 01：学习路线与能力自测","description":"用读文档、定位报错、写协作材料和说明技术方案四类任务建立程序员英语学习路线。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"程序员英语","summary":"用读文档、定位报错、写协作材料和说明技术方案四类任务建立程序员英语学习路线。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":false,"next":{"text":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary"}},"headers":[],"relativePath":"life/english/programmer/overview.md","filePath":"life/english/programmer/overview.md"}'),l={name:"life/english/programmer/overview.md"};function o(n,e,d,s,c,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="程序员英语-01-学习路线与能力自测" tabindex="-1">程序员英语 01：学习路线与能力自测 <a class="header-anchor" href="#程序员英语-01-学习路线与能力自测" aria-label="Permalink to &quot;程序员英语 01：学习路线与能力自测&quot;">​</a></h1><p>程序员英语首先解决一个具体问题：你能否从英文材料中提取约束，并让别人准确理解你的代码和判断。会认很多单词，却漏掉文档里的否定条件，仍然可能写出错误实现；句子不复杂，但把触发条件和证据说清楚，就已经能参与协作。</p><p>本系列面向能读简单英文句子、掌握一种编程语言的读者。语法基础薄弱时，可同时学习<a href="/life/english/new-concept/overview">新概念英语</a>，无需等学完四册再开始技术阅读。所有情境、数字、对话和题目均为原创教学示例。</p><h2 id="先做一个小测验" tabindex="-1">先做一个小测验 <a class="header-anchor" href="#先做一个小测验" aria-label="Permalink to &quot;先做一个小测验&quot;">​</a></h2><p>阅读下面的虚构工具说明，然后回答问题：</p><blockquote><p>The tool skips empty files by default. To include them, pass the <code>--include-empty</code> flag. This flag does not change how hidden files are handled.</p></blockquote><ol><li>默认处理空文件吗？</li><li>怎样包含空文件？</li><li>加上这个选项后，隐藏文件一定会被处理吗？</li><li>用一句英文说明这个选项的作用。</li></ol><details class="details custom-block"><summary>查看答案与讲解</summary><ol><li>不处理，<code>skips</code> 是跳过，<code>by default</code> 限定默认行为。</li><li>传入 <code>--include-empty</code>。</li><li>无法由这段话确定。它只说隐藏文件的处理规则不变，没有说明原规则。</li><li>示例：<code>The --include-empty flag includes empty files without changing the handling of hidden files.</code></li></ol><p>前三题检验是否保留条件与信息边界，第四题检验能否重新组织信息。照抄说明不能替代复述。</p></details><h2 id="按实际任务学习" tabindex="-1">按实际任务学习 <a class="header-anchor" href="#按实际任务学习" aria-label="Permalink to &quot;按实际任务学习&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>完成后应能交出的结果</th></tr></thead><tbody><tr><td>02</td><td><a href="/life/english/programmer/vocabulary">技术词汇与句子骨架</a></td><td>一张含英文例句、技术含义和易混点的词汇卡</td></tr><tr><td>03</td><td><a href="/life/english/programmer/reading-docs">读懂文档中的条件与约束</a></td><td>一份默认值、前提、例外与未知项清单</td></tr><tr><td>04</td><td><a href="/life/english/programmer/errors-search">读报错、搜索与求助</a></td><td>一段能让别人开始排查的问题描述</td></tr><tr><td>05</td><td><a href="/life/english/programmer/issue-pr">写 Issue、Commit 与 PR</a></td><td>包含复现步骤和验证结果的协作文本</td></tr><tr><td>06</td><td><a href="/life/english/programmer/review-writing">代码评审与技术说明</a></td><td>有证据、理由和下一步的评审意见</td></tr><tr><td>07</td><td><a href="/life/english/programmer/listening-speaking">会议、听力与技术表达</a></td><td>一分钟说明和一份确认过的行动记录</td></tr><tr><td>08</td><td><a href="/life/english/programmer/practice">综合实战与复习</a></td><td>从阅读到提交说明的一套完整材料</td></tr></tbody></table><p>每次练习可以安排 25 分钟：5 分钟重做旧题，10 分钟读一小段材料，10 分钟用自己的话写或说。时间只是起点；若一句话的条件仍没读清，就缩短材料，不靠延长词表掩盖问题。</p><p>第一周练词汇和文档，第二周练报错和 Issue，第三周练 PR 与评审，第四周完成口头说明和综合任务。已有经验的读者可直接从综合任务查漏补缺。这是建议节奏，不是四周熟练的承诺。</p><h2 id="怎样判断进步" tabindex="-1">怎样判断进步 <a class="header-anchor" href="#怎样判断进步" aria-label="Permalink to &quot;怎样判断进步&quot;">​</a></h2><p>把同一任务的初稿和修改稿保留下来，分别检查四件事：事实是否准确、条件是否完整、读者能否行动、表达是否简洁。每项记 0 分（缺失）、1 分（需要追问）、2 分（独立可用）。重复遗漏同一条件，比偶尔拼错一个词更值得优先修正。</p><p>可以用词典、翻译或 AI 辅助，但先写自己的理解，再逐项核对原文。特别检查 <code>not</code>、<code>only</code>、<code>unless</code>、数字、单位和版本；工具改稿不能新增你没验证的结论。不要把真实凭据、客户数据或内部日志贴进公开练习材料。</p><h2 id="资料与延伸" tabindex="-1">资料与延伸 <a class="header-anchor" href="#资料与延伸" aria-label="Permalink to &quot;资料与延伸&quot;">​</a></h2><p><a href="https://developers.google.com/tech-writing/one" target="_blank" rel="noopener noreferrer">Google Technical Writing One</a> 是技术写作入门课程，强调术语、句子、段落与读者。本站围绕开发工作安排练习，课程本身不等同于完整的英语听说训练。可以用课程中的一小节作精读材料，再完成本站相应任务。</p>',17)])])}const m=t(l,[["render",o]]);export{g as __pageData,m as default};
